package runtime

import (
	"bytes"
	"encoding/base64"
	"encoding/json"
	"image"
	_ "image/gif"
	_ "image/jpeg"
	_ "image/png"
)

const ImageCompletedEvent = "output.image.completed"
const ImageArtifactEvent = "output.image.artifact"
const MaximumImageBytes = 4 << 20
const MaximumImagePixels = 16 << 20
const MaximumImageDimension = 8192
const ImagePreview = "Generated image retained."

// CompletedImage carries exact generated bytes to the governed sink. It is
// internal and must never be stored directly in the public event journal.
type CompletedImage struct {
	Data string `json:"data"`
}

func (value CompletedImage) Payload() map[string]any { return map[string]any{"data": value.Data} }

type ImageContent struct {
	Bytes         []byte
	MediaType     string
	Width, Height int
}

func ParseCompletedImage(payload map[string]any) (ImageContent, error) {
	data, ok := payload["data"].(string)
	if !ok || len(payload) != 1 || len(data) == 0 || len(data) > base64.StdEncoding.EncodedLen(MaximumImageBytes) {
		return ImageContent{}, ErrProtocol
	}
	content, err := base64.StdEncoding.Strict().DecodeString(data)
	if err != nil || len(content) == 0 || len(content) > MaximumImageBytes || base64.StdEncoding.EncodeToString(content) != data {
		return ImageContent{}, ErrProtocol
	}
	config, format, err := image.DecodeConfig(bytes.NewReader(content))
	if err != nil || !validImageDimensions(config.Width, config.Height) {
		return ImageContent{}, ErrProtocol
	}
	mediaType := "image/" + format
	if !validImageMediaType(mediaType) {
		return ImageContent{}, ErrProtocol
	}
	// Check the complete first image only after bounding its decoded allocation.
	// Original bytes, including metadata and additional GIF frames, are retained.
	decoded, decodedFormat, err := image.Decode(bytes.NewReader(content))
	if err != nil || decodedFormat != format || decoded.Bounds().Empty() || !decoded.Bounds().In(image.Rect(0, 0, config.Width, config.Height)) {
		return ImageContent{}, ErrProtocol
	}
	return ImageContent{Bytes: content, MediaType: mediaType, Width: config.Width, Height: config.Height}, nil
}
func validImageMediaType(value string) bool {
	return value == "image/png" || value == "image/jpeg" || value == "image/gif"
}
func validImageDimensions(width, height int) bool {
	return width > 0 && height > 0 && width <= MaximumImageDimension && height <= MaximumImageDimension && int64(width)*int64(height) <= MaximumImagePixels
}

type ImageArtifact struct {
	ArtifactID string `json:"artifactId"`
	Digest     string `json:"digest"`
	SizeBytes  int64  `json:"sizeBytes"`
	MediaType  string `json:"mediaType"`
	Width      int    `json:"width"`
	Height     int    `json:"height"`
	Preview    string `json:"preview"`
}

func (value ImageArtifact) Payload() map[string]any {
	return map[string]any{"artifactId": value.ArtifactID, "digest": value.Digest, "sizeBytes": value.SizeBytes, "mediaType": value.MediaType, "width": value.Width, "height": value.Height, "preview": value.Preview}
}
func ParseImageArtifact(payload map[string]any) (ImageArtifact, error) {
	var value ImageArtifact
	if len(payload) != 7 {
		return value, ErrProtocol
	}
	for _, key := range []string{"artifactId", "digest", "mediaType", "preview"} {
		if _, ok := payload[key].(string); !ok {
			return value, ErrProtocol
		}
	}
	encoded, err := json.Marshal(payload)
	if err != nil || json.Unmarshal(encoded, &value) != nil || !runtimeArtifactID.MatchString(value.ArtifactID) || !runtimeArtifactDigest.MatchString(value.Digest) || value.SizeBytes <= 0 || value.SizeBytes > MaximumImageBytes || !validImageMediaType(value.MediaType) || !validImageDimensions(value.Width, value.Height) || value.Preview != ImagePreview {
		return ImageArtifact{}, ErrProtocol
	}
	return value, nil
}
